CREATE TABLE analytics.events_reordered
(
    event_id String,
    region String,
    event_ts DateTime,
    amount Float64
)
ENGINE = MergeTree()
ORDER BY (region, event_ts, event_id);

INSERT INTO analytics.events_reordered
SELECT event_id, region, event_ts, amount
FROM analytics.events;

RENAME TABLE analytics.events TO analytics.events_old, analytics.events_reordered TO analytics.events;
DROP TABLE analytics.events_old;
OPTIMIZE TABLE analytics.events FINAL;
SQL"

